mapper.select:
SELECT u.id, u.uid, u.user_name, u.nike_name, u.email, u.avatar, u.status, u.type, u.is_vip, u.vip_expire_time, u.role_id, u.create_time,u.sex,u.descript, r.name AS role_name,r.level FROM public.user_info u LEFT JOIN public.role r ON u.role_id = r.id
u.is_delete = 0
AND u.user_name LIKE CONCAT('%', #{userName}, '%')
AND u.nike_name LIKE CONCAT('%', #{nikeName}, '%')
AND u.email LIKE CONCAT('%', #{email}, '%')
AND u.status = #{status}
AND u.role_id = #{roleId}
AND u.type = #{type}
AND u.is_vip = #{isVip}
ORDER BY u.create_time DESC
